select
  TEST_NO, PRIORITY_INDICATOR, PATIENT_ID, VISIT_ID, WORKING_ID, EXECUTE_DATE, NAME, NAME_PHONETIC, CHARGE_TYPE, SEX, AGE, SUBJECT, TEST_CAUSE, RELEVANT_CLINIC_DIAG, SPECIMEN, NOTES_FOR_SPCM, SPCM_SAMPLE_DATE_TIME, SPCM_RECEIVED_DATE_TIME, REQUESTED_DATE_TIMEColumn1, ORDERING_DEPT, ORDERING_PROVIDER, PERFORMED_BY, RESULT_STATUS, RESULTS_RPT_DATE_TIME, TRANSCRIPTIONIST, VERIFIED_BY, COSTS, CHARGES, BILLING_INDICATOR, PRINT_INDICATOR
from lab_test_master


        and TEST_NO = #{testNo}


        and PRIORITY_INDICATOR = #{priorityIndicator}


        and PATIENT_ID = #{patientId}


        and VISIT_ID = #{visitId}


        and WORKING_ID = #{workingId}


        and EXECUTE_DATE = #{executeDate}


        and NAME = #{name}


        and NAME_PHONETIC = #{namePhonetic}


        and CHARGE_TYPE = #{chargeType}


        and SEX = #{sex}


        and AGE = #{age}


        and SUBJECT = #{subject}


        and TEST_CAUSE = #{testCause}


        and RELEVANT_CLINIC_DIAG = #{relevantClinicDiag}


        and SPECIMEN = #{specimen}


        and NOTES_FOR_SPCM = #{notesForSpcm}


        and SPCM_SAMPLE_DATE_TIME = #{spcmSampleDateTime}


        and SPCM_RECEIVED_DATE_TIME = #{spcmReceivedDateTime}


        and REQUESTED_DATE_TIMEColumn1 = #{requestedDateTimecolumn1}


        and ORDERING_DEPT = #{orderingDept}


        and ORDERING_PROVIDER = #{orderingProvider}


        and PERFORMED_BY = #{performedBy}


        and RESULT_STATUS = #{resultStatus}


        and RESULTS_RPT_DATE_TIME = #{resultsRptDateTime}


        and TRANSCRIPTIONIST = #{transcriptionist}


        and VERIFIED_BY = #{verifiedBy}


        and COSTS = #{costs}


        and CHARGES = #{charges}


        and BILLING_INDICATOR = #{billingIndicator}


        and PRINT_INDICATOR = #{printIndicator}


limit #{pageable.offset}, #{pageable.pageSize}

